operations.text:
query CCBFormsQuery {
  ccbFormsV2 {
    __typename
    ... on CCBFormsSuccess {
      forms {
        title
        url
      }
    }
    ... on CCBFormsFetchError {
      message
    }
    ... on CCBFormsNotFoundError {
      message
    }
  }
}

query CampusesQuery(
  $preferredCampus: String
) {
  campusesV2(preferredCampus: $preferredCampus) {
    __typename
    ... on CampusesSuccess {
      campuses {
        slug
        content
        campusName
        facebook
        instagram
        giving
        givingPlatforms {
          icon
          link
          title
          text
        }
        location
        isPreferred
        cityState
        image
        streamLink
        campusLead {
          name
          image
          subTitle
        }
        campusLeads: leadPastor {
          slug
          name
          image
          leadershipGroup
        }
      }
    }
    ... on CampusesFetchError {
      message
    }
    ... on CampusesNotFoundError {
      message
    }
  }
}

query CoreDataQuery {
  core {
    giving {
      featureImge
      copy
    }
    profile {
      featureImge
      copy
    }
    sermons {
      featureImge
      copy
    }
    hccexpression {
      featureImge
      copy
    }
    events {
      featureImge
      copy
    }
    more {
      featureImge
      copy
      links {
        title
        link
        iconName
        subTitle
        group
      }
    }
  }
}

query EventDetailQuery(
  $slug: String!
  $campusSlug: String!
) {
  events(slug: $slug, campusSlug: $campusSlug) {
    description
    eventDate
    eventImageUrl
    eventTime
    eventTitle
    pageTitle
    reoccurring
    slug
    eventMonth
    pageName
    content
    sessions {
      id
      startsAt
      label
    }
    zoomLink
    eventSpeakers {
      fullName
      image
    }
    room
  }
}

query LatestEventsQuery(
  $campusSlug: String!
) {
  upcomingEventsByMonth(campusSlug: $campusSlug) {
    __typename
    ... on UpcomingEventsByMonthSuccess {
      months {
        month
        year
        events {
          eventTitle
          eventDate
          description
          slug
          eventSpeakers {
            image
          }
        }
      }
    }
    ... on UpcomingEventsByMonthFetchError {
      message
    }
  }
}

query LatestSermonsQuery {
  sermons(first: 3) {
    edges {
      node {
        slug
        title
        thumbnail
        speakerFullName
        speakerImage
        youtubeLink
        id
      }
    }
  }
}

query SermonsContainerQuery {
  ...SermonsItemsFragment
}

fragment SermonsItemsFragment on Query {
  sermons(first: 10) {
    edges {
      node {
        slug
        title
        thumbnail
        speakerFullName
        speakerImage
        youtubeLink
        pageName
        id
        __typename
      }
      cursor
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query SermonsItemsRefetchQuery(
  $count: Int = 10
  $cursor: String
) {
  ...SermonsItemsFragment_1G22uz
}

fragment SermonsItemsFragment_1G22uz on Query {
  sermons(first: $count, after: $cursor) {
    edges {
      node {
        slug
        title
        thumbnail
        speakerFullName
        speakerImage
        youtubeLink
        pageName
        id
        __typename
      }
      cursor
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query ThoughtOfGodImplQuery {
  thoughtOfGod {
    description
    thumbnail
    title
    blogs {
      date
      description
      link
      thumbnail
      title
    }
    youtube {
      body
      thumbnail
      title
      youtubeLink
    }
  }
}

query ThoughtOfGodQuery {
  thoughtOfGod {
    description
    thumbnail
    title
  }
}

query VerseOfTheDayQuery {
  verseOfTheDayV2 {
    __typename
    ... on Scripture {
      book
      date
      image
      stBook
      text
      verseId
    }
    ... on VodFetchError {
      message
    }
    ... on VodNotFoundError {
      message
    }
  }
}
